/* Shell: the platform header carries the app's name; the app draws its own navigation only. */
if(!sections.some(s=>s.id===st.section))st.section=(sections[0]||SCREENS[0]).id;
prefetch(screenRoles(st.section,st));
const MAIN={overview,updates:updatesScreen,investors:investorsScreen,plans:plansScreen,settings:settingsScreen};
let main='',overlay='';
try{const p=st.panel;
 if(p&&p.type==='update'){const u=UPD()[p.id];main=u?updateView(u)+blockEditor(u):(PENDING.size?'':MAIN[st.section]());if(!u&&!PENDING.size)st.panel=null;}
 else if(p&&p.type==='send'){const u=UPD()[p.id];main=u?sendView(u):MAIN[st.section]();}
 else main=MAIN[st.section]();}catch(e){main=PENDING.size?'':card('',muted('This screen could not be shown: '+String(e&&e.message||e).slice(0,200)));}
try{if(!(st.panel&&['update','send'].includes(st.panel.type)))overlay=sidePanel();}catch(e){overlay=PENDING.size?'':kit.panel({title:'Details',close:'close',body:muted('This panel could not be shown: '+String(e&&e.message||e).slice(0,200))});}
if(PENDING.size){main=LOADING;overlay='';}
else if(!NOTICE){const probs=readProblemsNow();if(probs.length)note('Some records could not be read, so changes are paused: '+probs[0],'error');else if(!inp.saved)note('Preview: nothing is saved or sent from here.','info');}
const navItems=sections.map(s=>({id:s.id,label:screenLabel(s.id)}));
const wideNav=!(inp.viewport&&inp.viewport.width==='phone');
const html=kit.page((overlay?'<div class="iu-under" inert>':'<div>')+kit.layout(kit.nav(navItems,st.section,{side:wideNav,label:st.layout.heading}),'<div class="iu-screen">'+main+'</div>',{side:wideNav})+'</div>'+overlay);
const ctx=st.panel&&['update','send'].includes(st.panel.type)?{update:st.panel.id}:null;
return {html,css:typeof INVESTOR_UPDATES_CSS==='string'?INVESTOR_UPDATES_CSS:'',state:st,...(NOTICE?{notice:kit.notice(NOTICE.kind,NOTICE.message)}:{}),...(inp.saved&&JSON.stringify(ctx)!==JSON.stringify(inp.context===undefined?null:inp.context)?{context:ctx}:{})};
